def estimate_tokens(text: str) -> int:
    # Dependency-free heuristic: ~4 chars/token in English-like text.
    # Good enough for deciding when to compact.
    return max(1, int(len(text) / 4))

class _StoredMessage:
    message: Message
    tokens: int

class ContextManager:
    """Tracks conversation and compacts it when it grows too large.

    - Keeps last `keep_last_messages` intact.
    - Summarizes older messages using the same LLM (when possible).
    """

    def __init__(
        self,
        model: str,
        max_tokens: int = 8000,
        keep_last_messages: int = 12,
        summarizer_model: str | None = None,
    ):
        self.model = model
        self.summarizer_model = summarizer_model or model
        self.max_tokens = max_tokens
        self.keep_last_messages = keep_last_messages
        self._history: list[_StoredMessage] = []

    def add(self, role: str, content: str) -> None:
        msg = {"role": role, "content": content}
        self._history.append(_StoredMessage(message=msg, tokens=estimate_tokens(content)))
        self._compact_if_needed()

    def extend(self, messages: list[Message]) -> None:
        for m in messages:
            self.add(m["role"], m["content"])

    def messages(self) -> list[Message]:
        return [m.message for m in self._history]

    def token_count(self) -> int:
        return sum(m.tokens for m in self._history)

    def _compact_if_needed(self) -> None:
        if self.token_count() <= self.max_tokens:
            return
        if len(self._history) <= self.keep_last_messages:
            return

        keep = self._history[-self.keep_last_messages :]
        old = self._history[: -self.keep_last_messages]
        summary = self._summarize(old)
        self._history = [_StoredMessage(message={"role": "system", "content": summary}, tokens=estimate_tokens(summary))] + keep

    def _summarize(self, items: list[_StoredMessage]) -> str:
        # If summarization fails, fall back to a compact heuristic.
        transcript = []
        for it in items:
            role = it.message["role"]
            content = it.message["content"].strip()
            transcript.append(f"{role}: {content}")

        prompt = """Summarize the prior conversation for a coding agent.

Keep:
- user goals and constraints
- decisions made
- files mentioned
- TODOs / open questions

Write a concise bullet summary.
""".strip()

        try:
            resp = litellm.completion(
                model=self.summarizer_model,
                messages=[
                    {"role": "system", "content": prompt},
                    {"role": "user", "content": "\n\n".join(transcript)},
                ],
                temperature=0.2,
            )
            return resp["choices"][0]["message"]["content"].strip()
        except Exception:
            # Heuristic fallback
            user_lines = [t for t in transcript if t.startswith("user:")]
            assistant_lines = [t for t in transcript if t.startswith("assistant:")]
            return (
                "Earlier conversation summary:\n"
                f"- User messages: {len(user_lines)}\n"
                f"- Assistant messages: {len(assistant_lines)}\n"
                + (f"- Recent user topics: {', '.join([l[6:][:80] for l in user_lines[-3:]])}\n" if user_lines else "")
            ).strip()

def add(self, role: str, content: str) -> None:
    msg = {"role": role, "content": content}
    self._history.append(_StoredMessage(message=msg, tokens=estimate_tokens(content)))
    self._compact_if_needed()

def extend(self, messages: list[Message]) -> None:
    for m in messages:
        self.add(m["role"], m["content"])

def _compact_if_needed(self) -> None:
    if self.token_count() <= self.max_tokens:
        return
    if len(self._history) <= self.keep_last_messages:
        return

    keep = self._history[-self.keep_last_messages :]
    old = self._history[: -self.keep_last_messages]
    summary = self._summarize(old)
    self._history = [_StoredMessage(message={"role": "system", "content": summary}, tokens=estimate_tokens(summary))] + keep

def _iter_files(pattern: str) -> Iterable[Path]:
    root = _workspace_root()
    yield from root.glob(pattern)

def _safe_read(p: Path) -> str | None:
    try:
        return p.read_text(encoding="utf-8")
    except Exception:
        return None

def for_embedding(self) -> str:
    header = f"{self.kind} {self.name} ({self.filepath}:{self.start_line}-{self.end_line})"
    return f"{header}\n\n{self.code}"

def get_segment(node: ast.AST) -> tuple[int, int, str] | None:
    if not hasattr(node, "lineno") or not hasattr(node, "end_lineno"):
        return None
    start = int(getattr(node, "lineno"))
    end = int(getattr(node, "end_lineno"))
    seg = "\n".join(lines[start - 1 : end])
    return start, end, seg

def _cache_key(self) -> str:
    root = str(_workspace_root())
    return _sha1(f"{root}|{self.embedder_model}|{self.index_pattern}")

def _load_cache(self) -> bool:
    meta_path, vecs_path = self._paths()
    if not meta_path.exists() or not vecs_path.exists():
        return False

    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
        file_metas: dict[str, float] = meta.get("files", {})
        # Validate mtimes
        for fp, mtime in file_metas.items():
            p = _workspace_root() / fp
            if not p.exists() or abs(p.stat().st_mtime - float(mtime)) > 1e-6:
                return False

        self._chunks = [CodeChunk(**c) for c in meta["chunks"]]
        self._embeddings = np.load(vecs_path)
        if self._embeddings.ndim != 2 or self._embeddings.shape[0] != len(self._chunks):
            return False
        return True
    except Exception:
        return False

def ensure_index(self, progress_cb: Any | None = None) -> None:
    """Build or load the index."""
    if self._embeddings is not None and self._chunks:
        return

    if self._load_cache():
        if progress_cb:
            progress_cb(f"RAG: loaded cached index with {len(self._chunks)} chunks")
        return

    root = _workspace_root()
    files = [p for p in _iter_files(self.index_pattern) if p.is_file()]
    file_metas = {str(p.resolve().relative_to(root)): p.stat().st_mtime for p in files}

    chunks: list[CodeChunk] = []
    for i, p in enumerate(files):
        if progress_cb and i % 25 == 0:
            progress_cb(f"RAG: parsing {i+1}/{len(files)} files")
        text = _safe_read(p)
        if text is None:
            continue
        rel = _relpath(p)
        if p.suffix == ".py":
            chunks.extend(_extract_python_chunks(text, rel))
        else:
            cid = _sha1(f"file:{rel}")
            chunks.append(
                CodeChunk(
                    id=cid,
                    filepath=rel,
                    kind="module",
                    name=p.name,
                    start_line=1,
                    end_line=max(1, len(text.splitlines())),
                    code=text,
                )
            )

    if not chunks:
        self._chunks = []
        self._embeddings = np.zeros((0, 1), dtype=np.float32)
        return

    # Embed in batches
    texts = [c.for_embedding() for c in chunks]
    vectors: list[list[float]] = []
    batch_size = 32
    for start in range(0, len(texts), batch_size):
        end = min(len(texts), start + batch_size)
        if progress_cb:
            progress_cb(f"RAG: embedding chunks {start+1}-{end}/{len(texts)}")
        resp = litellm.embedding(model=self.embedder_model, input=texts[start:end])
        # litellm returns {"data": [{"embedding": [...]}, ...]}
        data = resp.get("data", [])
        for item in data:
            vectors.append(item["embedding"])

    emb = np.array(vectors, dtype=np.float32)
    # Normalize for cosine similarity
    norms = np.linalg.norm(emb, axis=1, keepdims=True) + 1e-12
    emb = emb / norms

    self._chunks = chunks
    self._embeddings = emb
    self._save_cache(file_metas)
    if progress_cb:
        progress_cb(f"RAG: indexed {len(files)} files into {len(chunks)} chunks")

def _extract_json_object(text: str) -> dict[str, Any] | None:
    """Extract the first JSON object from model output."""
    try:
        return json.loads(text)
    except Exception:
        pass

    m = re.search(r"\{.*\}", text, flags=re.DOTALL)
    if not m:
        return None
    try:
        return json.loads(m.group(0))
    except Exception:
        return None

class Agent:
    """SimpleCoder CLI agent.

    - ReAct-style loop: decide -> tool -> observe -> repeat.
    - Optional planning: decomposes task, tracks completion.
    - Optional RAG: AST-chunked embedding search with disk cache.
    - Permissions: asks before filesystem writes/edits.
    """

    def __init__(
        self,
        model: str,
        max_iterations: int = 10,
        verbose: bool = False,
        use_planning: bool = False,
        use_rag: bool = False,
        rag_embedder: str = "gemini/gemini-embedding-001",
        rag_index_pattern: str = "**/*.py",
    ):
        self.cfg = _RunConfig(
            model=model,
            max_iterations=max_iterations,
            verbose=verbose,
            use_planning=use_planning,
            use_rag=use_rag,
            rag_embedder=rag_embedder,
            rag_index_pattern=rag_index_pattern,
        )

        self.permission_manager = create_permission_manager()
        self.tools = ToolRegistry(self.permission_manager)
        self.ctx = ContextManager(model=model, max_tokens=8000, keep_last_messages=12)
        self.planner = TaskPlanner(model=model)

        self.rag: CodeRAG | None = None
        if use_rag:
            self.rag = CodeRAG(embedder_model=rag_embedder, index_pattern=rag_index_pattern)

        self._plan: list[Subtask] | None = None

    def run(self, user_input: str) -> str:
        if self.cfg.use_planning and self._plan is None:
            self._plan = self._create_plan(user_input)

        if self.cfg.use_planning and self._plan:
            # Work through subtasks in order; each subtask gets its own ReAct run.
            outputs: list[str] = [TaskPlanner.render_plan_md(self._plan)]
            for st in self._plan:
                if st.status == "completed":
                    continue
                st.status = "in_progress"
                outputs.append(f"\n### Working on: {st.id}\n{st.description}")
                out = self._react(st.description, plan=self._plan)
                outputs.append(out)
                # Mark complete unless the model explicitly says it's blocked.
                st.status = "completed" if "BLOCKED" not in out else "blocked"
                outputs.insert(0, TaskPlanner.render_plan_md(self._plan))
            return "\n\n".join([o for o in outputs if o.strip()])

        return self._react(user_input, plan=self._plan)

    def _create_plan(self, task: str) -> list[Subtask]:
        if self.cfg.verbose:
            console.print("[cyan]Planning...[/cyan]")
        try:
            plan = self.planner.make_plan(task)
        except Exception as e:
            if self.cfg.verbose:
                console.print(f"[yellow]Planning failed, continuing without plan: {e}[/yellow]")
            return []
        if self.cfg.verbose and plan:
            console.print(self.planner.render_plan_md(plan))
        return plan

    def _progress(self, msg: str) -> None:
        if self.cfg.verbose:
            console.print(f"[dim]{msg}[/dim]")

    def _react(self, task: str, plan: list[Subtask] | None) -> str:
        system_prompt = self._system_prompt()

        self.ctx.add("system", system_prompt)
        self.ctx.add("user", task)

        if self.rag is not None:
            # Ensure index (cached)
            try:
                self.rag.ensure_index(progress_cb=self._progress)
                hits = self.rag.search(task, top_k=5)
                if hits:
                    rag_md = self._format_rag(hits)
                    self.ctx.add("system", f"Relevant code context (RAG):\n{rag_md}")
            except Exception as e:
                self._progress(f"RAG disabled due to error: {e}")

        tool_desc = json.dumps(self.tools.list_tools(), indent=2)
        self.ctx.add("system", f"Available tools (JSON):\n{tool_desc}")

        last_answer = ""

        with Progress(
            SpinnerColumn(),
            TextColumn("{task.description}"),
            transient=True,
            console=console,
            disable=not self.cfg.verbose,
        ) as progress:
            task_id = progress.add_task("Thinking...", total=None)
            for i in range(self.cfg.max_iterations):
                progress.update(task_id, description=f"Iteration {i+1}/{self.cfg.max_iterations}")
                model_out = self._call_model(self.ctx.messages())
                last_answer = model_out

                parsed = _extract_json_object(model_out)
                if not parsed:
                    # Not structured; treat as final.
                    return self._wrap_final(plan, model_out)

                if parsed.get("type") == "final":
                    return self._wrap_final(plan, str(parsed.get("answer", "")).strip())

                if parsed.get("type") != "tool":
                    # Unknown shape; treat as final.
                    return self._wrap_final(plan, model_out)

                tool_name = str(parsed.get("name", ""))
                args = parsed.get("args", {})
                if not isinstance(args, dict):
                    args = {}

                self._progress(f"Tool call: {tool_name}({args})")
                try:
                    result = self.tools.execute(tool_name, args)
                except Exception as e:
                    result = {"error": str(e)}

                self.ctx.add("assistant", model_out)
                self.ctx.add("tool", json.dumps({"name": tool_name, "result": result}, indent=2))

                # If the tool produced an error, encourage recovery.
                if isinstance(result, dict) and result.get("error"):
                    self.ctx.add(
                        "system",
                        "The previous tool call failed. Either try a different tool, fix args, or ask a clarifying question.",
                    )

        return self._wrap_final(plan, last_answer)

    def _call_model(self, messages: list[dict[str, str]]) -> str:
        # Streaming: print deltas in verbose mode, but still return full content.
        if self.cfg.verbose:
            try:
                chunks = []
                for part in litellm.completion(
                    model=self.cfg.model,
                    messages=messages,
                    temperature=0.2,
                    stream=True,
                ):
                    delta = part["choices"][0].get("delta", {}).get("content")
                    if delta:
                        chunks.append(delta)
                        console.print(delta, end="")
                console.print()  # newline after streamed output
                return "".join(chunks).strip()
            except Exception:
                # Fall back to non-stream
                pass

        try:
            resp = litellm.completion(model=self.cfg.model, messages=messages, temperature=0.2)
            return resp["choices"][0]["message"]["content"].strip()
        except Exception as e:
            # Return a structured final response so the CLI doesn't crash.
            msg = (
                "LLM call failed. This is usually a missing/invalid API key or provider config.\n\n"
                "Fix by setting the right environment variables for your provider (e.g. `GEMINI_API_KEY`).\n\n"
                f"Error: {type(e).__name__}: {e}"
            )
            return json.dumps({"type": "final", "answer": msg})

    def _system_prompt(self) -> str:
        return (
            "You are SimpleCoder, a CLI coding agent. "
            "Use a ReAct loop. When you need information or to change files, call a tool. "
            "You MUST respond with JSON only, no backticks, no extra text.\n\n"
            "Two allowed JSON shapes:\n"
            "1) Tool call: {\"type\":\"tool\", \"name\": <tool_name>, \"args\": {...}}\n"
            "2) Final answer: {\"type\":\"final\", \"answer\": <string>}\n\n"
            "Guidelines:\n"
            "- Prefer read/search tools before editing.\n"
            "- When writing/editing, be surgical and explain what changed.\n"
            "- If blocked, ask a single clear question in the final answer."
        )

    def _format_rag(self, hits: list[dict[str, Any]]) -> str:
        lines = []
        for h in hits:
            loc = f"{h['filepath']}:{h['start_line']}-{h['end_line']}"
            lines.append(f"- {h['kind']} {h['name']} @ {loc} (score={h['score']:.3f})")
            lines.append("```")
            lines.append(h["code"].strip())
            lines.append("```")
        return "\n".join(lines)

    def _wrap_final(self, plan: list[Subtask] | None, answer: str) -> str:
        if plan:
            return f"{TaskPlanner.render_plan_md(plan)}\n\n{answer}".strip()
        return answer.strip()

